namespace Tsumo.Tests
{
    public class ContentPageSource
    {
        public string sourcePath;
        public string section;
        public string type;
        public string slug;
        public string title;
        public Tsonic.CSharp.Js.Date dateUtc;
        public string dateString;
        public string lastmodString;
        public bool draft;
        public bool leafBundle;
        public string description;
        public Tsonic.CSharp.Js.JSArray<string> tags;
        public Tsonic.CSharp.Js.JSArray<string> categories;
        public Tsonic.CSharp.Js.Map<string, ParamValue> parameters;
        public string rawBody;
        public string relPermalink;
        public string outputRelPath;
        public string? layout;
        public PageFile file;
        public Tsonic.CSharp.Js.JSArray<FrontMatterMenu> menus;
        public ContentPageSource(string sourcePath, string section, string type, string slug, string title, Tsonic.CSharp.Js.Date dateUtc, string dateString, string lastmodString, bool draft, bool leafBundle, string description, Tsonic.CSharp.Js.JSArray<string> tags, Tsonic.CSharp.Js.JSArray<string> categories, Tsonic.CSharp.Js.Map<string, ParamValue> parameters, string rawBody, string relPermalink, string outputRelPath, string? layout, PageFile file, Tsonic.CSharp.Js.JSArray<FrontMatterMenu> menus)
        {
            this.sourcePath = sourcePath;
            this.section = section;
            this.type = type;
            this.slug = slug;
            this.title = title;
            this.dateUtc = dateUtc;
            this.dateString = dateString;
            this.lastmodString = lastmodString;
            this.draft = draft;
            this.leafBundle = leafBundle;
            this.description = description;
            this.tags = tags;
            this.categories = categories;
            this.parameters = parameters;
            this.rawBody = rawBody;
            this.relPermalink = relPermalink;
            this.outputRelPath = outputRelPath;
            this.layout = layout;
            this.file = file;
            this.menus = menus;
        }
    }
    public class ListPageSource
    {
        public string? title;
        public string rawBody;
        public string description;
        public string? type;
        public string? layout;
        public Tsonic.CSharp.Js.Map<string, ParamValue> parameters;
        public string sourceDir;
        public PageFile file;
        public ListPageSource(string? title, string rawBody, string description, string? type, string? layout, Tsonic.CSharp.Js.Map<string, ParamValue> parameters, string sourceDir, PageFile file)
        {
            this.title = title;
            this.rawBody = rawBody;
            this.description = description;
            this.type = type;
            this.layout = layout;
            this.parameters = parameters;
            this.sourceDir = sourceDir;
            this.file = file;
        }
    }
    public class ContentInventory
    {
        public Tsonic.CSharp.Js.JSArray<ContentPageSource> pages;
        public Tsonic.CSharp.Js.Map<string, ListPageSource> listPagesByRoute;
        public ContentInventory(Tsonic.CSharp.Js.JSArray<ContentPageSource> pages, Tsonic.CSharp.Js.Map<string, ListPageSource> listPagesByRoute)
        {
            this.pages = pages;
            this.listPagesByRoute = listPagesByRoute;
        }
    }
}
